//! `flowster-wasm`: the engine as a WASM module for the Engine Worker (SPEC §5.1).
//!
//! JS surface (generated by wasm-bindgen; used by `ui/src/engine/engine.worker.ts`):
//! * `new WasmEngine()`, `.open(id, fileName, bytes)`, `.request(id, req)`:
//!   both return an array of `EngineEvent` objects (§5.4);
//! * `derivedStateHash()`: determinism probe as JSON (`scripts/determinism-check.mjs`);
//! * `crdtSpike(library, shapes, reserveMiB?)`: CRDT spike report as JSON (`scripts/crdt-spike.mjs`);
//! * `heapStats()`: `{ live, peak, linear }` bytes, for the UI's status bar.

pub mod engine;

#[cfg(target_arch = "wasm32")]
mod wasm_alloc;

pub use engine::Engine;

#[cfg(target_arch = "wasm32")]
mod bindings {
    use wasm_bindgen::prelude::*;

    use crate::engine::Engine;
    use flowster_core::protocol::{EngineEvent, EngineRequest};

    #[wasm_bindgen(start)]
    pub fn start() {
        console_error_panic_hook::set_once();
    }

    fn to_js(events: &[EngineEvent]) -> Result<JsValue, JsValue> {
        use serde::Serialize;
        let ser = serde_wasm_bindgen::Serializer::json_compatible();
        events.serialize(&ser).map_err(|e| JsValue::from_str(&e.to_string()))
    }

    #[wasm_bindgen]
    pub struct WasmEngine {
        inner: Engine,
    }

    #[wasm_bindgen]
    impl WasmEngine {
        #[wasm_bindgen(constructor)]
        pub fn new() -> WasmEngine {
            WasmEngine { inner: Engine::new() }
        }

        pub fn open(&mut self, id: u32, file_name: &str, bytes: &[u8]) -> Result<JsValue, JsValue> {
            to_js(&self.inner.open(id, file_name, bytes))
        }

        pub fn request(&mut self, id: u32, req: JsValue) -> Result<JsValue, JsValue> {
            let events = match serde_wasm_bindgen::from_value::<EngineRequest>(req) {
                Ok(r) => self.inner.handle(id, r),
                Err(e) => vec![EngineEvent::Error { id: Some(id), message: format!("bad request: {e}") }],
            };
            to_js(&events)
        }
    }

    impl Default for WasmEngine {
        fn default() -> Self {
            Self::new()
        }
    }

    #[wasm_bindgen(js_name = heapStats)]
    pub fn heap_stats() -> String {
        let linear = core::arch::wasm32::memory_size(0) * 65536;
        format!(r#"{{"live":{},"peak":{},"linear":{}}}"#, crate::wasm_alloc::live(), crate::wasm_alloc::peak(), linear)
    }

    #[wasm_bindgen(js_name = derivedStateHash)]
    pub fn derived_state_hash() -> String {
        serde_json::to_string(&flowster_core::determinism::default_report()).unwrap()
    }

    #[cfg(feature = "spike")]
    #[wasm_bindgen(js_name = crdtSpike)]
    pub fn crdt_spike(library: &str, shapes: usize, reserve_mib: Option<u32>) -> Result<String, JsValue> {
        use flowster_crdt::spike::{SpikeConfig, run};
        #[wasm_bindgen]
        extern "C" {
            #[wasm_bindgen(js_namespace = performance)]
            fn now() -> f64;
        }
        struct WasmProbe;
        impl flowster_crdt::spike::Probe for WasmProbe {
            fn now_ms(&self) -> f64 {
                now()
            }
            fn live_bytes(&self) -> usize {
                crate::wasm_alloc::live()
            }
            fn reset_peak(&self) {
                crate::wasm_alloc::reset_peak()
            }
            fn peak_bytes(&self) -> usize {
                crate::wasm_alloc::peak()
            }
        }
        // Optionally grow linear memory up front, to separate `memory.grow` cost from library cost.
        let reserve_pages = reserve_mib.unwrap_or(0) as usize * 16;
        if reserve_pages > 0 {
            core::arch::wasm32::memory_grow(0, reserve_pages);
        }
        let cfg = SpikeConfig { shapes, ..SpikeConfig::default() };
        let mut report = match library {
            "loro" => run::<flowster_crdt::loro_store::LoroStore>(&cfg, &WasmProbe, "wasm32"),
            "yrs" => run::<flowster_crdt::yrs_store::YrsStore>(&cfg, &WasmProbe, "wasm32"),
            other => return Err(JsValue::from_str(&format!("unknown library {other}"))),
        };
        if reserve_pages > 0 {
            report.notes.push(format!("{} MiB of linear memory reserved before the run", reserve_mib.unwrap_or(0)));
        }
        let pages = core::arch::wasm32::memory_size(0);
        report.notes.push(format!("wasm linear memory after run: {} MiB", pages * 65536 / (1 << 20)));
        Ok(serde_json::to_string(&report).unwrap())
    }
}
